# adjacency with times
def analyze(evlist, delta=800):
    # times of each undirected pair
    pairs={}
    for u,v,t in evlist:
        k=(u,v) if u<v else (v,u)
        pairs.setdefault(k,[]).append(t)
    adj={}
    for (a,b),tl in pairs.items():
        adj.setdefault(a,{})[b]=tl
        adj.setdefault(b,{})[a]=tl
    closures=[]
    for (a,b),tl in pairs.items():
        na=adj[a]; nb=adj[b]
        common=set(na)&set(nb)
        common.discard(a); common.discard(b)
        for c in common:
            for tac in na[c]:
                for tbc in nb[c]:
                    est=max(tac,tbc)
                    for tab in tl:
                        if 0<tab-est<=delta:
                            closures.append((a,b,c,tac,tbc,tab))
    return closures,pairs,adj
